  "The app reads the names, birthdays and photos of contacts that have a birthday, so it can remind you. They stay on this phone and are never uploaded.": "ज्या कॉन्टॅक्ट्सचा वाढदिवस नोंदवलेला आहे, त्यांची नावं, वाढदिवस आणि फोटो ॲप वाचतं, जेणेकरून तुम्हाला आठवण करून देता येईल. ते याच फोनवर राहतात आणि कधीच अपलोड होत नाहीत.",
  "The bigger crackers cost gems. Everyday crackers and sparkler writing are always free.": "मोठ्या फटाक्यांसाठी जेम्स लागतात. रोजचे फटाके आणि फुलबाजीने लिहिणं नेहमीच मोफत.",
  "The camera is busy. Using the camera view instead.": "कॅमेरा व्यस्त आहे. त्याऐवजी कॅमेरा व्ह्यू वापरत आहोत.",
  "The headline flies across the sky; the message appears on the card.": "हेडलाइन आकाशात उडते; संदेश कार्डवर दिसतो.",
  "The link contains the whole card, so nothing is uploaded. Anyone who opens it sees the show.": "लिंकमध्ये संपूर्ण कार्ड आहे, त्यामुळे काहीच अपलोड होत नाही. जो कोणी ती उघडेल तो शो पाहील.",
  "The link contains the whole card, so nothing is uploaded. Host the game online (for example GitHub Pages or Netlify) so friends can open the link.": "लिंकमध्ये संपूर्ण कार्ड आहे, त्यामुळे काहीच अपलोड होत नाही. मित्रांना लिंक उघडता यावी म्हणून गेम ऑनलाइन होस्ट करा (उदा. GitHub Pages किंवा Netlify).",
