  "Premium dresses Diya Path in gold, with palace, river ghat and temple boards. Plus no ads and every cracker free.": "Premium पणती पथ सोन्याने सजवतं, महाल, नदीघाट आणि मंदिराच्या बोर्डसह. सोबत जाहिराती नाहीत आणि प्रत्येक फटाका मोफत.",
  "Golden diyas & royal boards": "सोनेरी पणत्या आणि शाही बोर्ड",
  "All styles": "सगळ्या स्टाइल",
  "India’s landmarks in 3D": "भारताची स्मारकं 3D मध्ये",
  "Walk the forecourt of all 15 landmarks in 3D and look around as the fireworks burst. Plus no ads and every cracker free.": "सगळ्या 15 स्मारकांच्या अंगणात 3D मध्ये फिरा आणि फटाके फुटताना चारी बाजूंना पाहा. सोबत जाहिराती नाहीत आणि प्रत्येक फटाका मोफत.",
  "Fireworks in your room with AR": "AR सोबत तुमच्या खोलीत आतषबाजी",
  "Point your camera and light crackers on your own floor and sky. Plus no ads and every cracker free.": "कॅमेरा फिरवा आणि तुमच्याच जमिनीवर व आकाशात फटाके फोडा. सोबत जाहिराती नाहीत आणि प्रत्येक फटाका मोफत.",
  "Sacred backgrounds for Diya Path": "पणती पथसाठी पवित्र पार्श्वभूमी",
  "Play before Lakshmi, Ganesha, Balaji, the Golden Temple and more. Plus no ads and every cracker free.": "लक्ष्मी, गणेश, बालाजी, सुवर्ण मंदिर आणि अधिकच्या समोर खेळा. सोबत जाहिराती नाहीत आणि प्रत्येक फटाका मोफत.",
  "Couldn’t load the plans from the store. Check you’re signed in and online, then try again.": "स्टोअरमधून प्लॅन लोड झाले नाहीत. तुम्ही साइन इन आणि ऑनलाइन आहात ते तपासा, मग पुन्हा प्रयत्न करा.",
  "See what Premium adds": "पाहा Premium काय जोडते",
  "Sacred backgrounds": "पवित्र पार्श्वभूमी",
  "Play Diya Path before Lakshmi, Ganesha, Balaji and more": "लक्ष्मी, गणेश, बालाजी आणि अधिकच्या समोर पणती पथ खेळा",
  "Sacred backgrounds: Lakshmi, Ganesha, Balaji and more": "पवित्र पार्श्वभूमी: लक्ष्मी, गणेश, बालाजी आणि अधिक",
  "All 10": "सर्व 10",
  "AR fireworks and sparkler in your room": "तुमच्या खोलीत AR आतषबाजी आणि फुलबाजी",
  "Free for everyone and included with every plan.": "सर्वांसाठी मोफत आणि प्रत्येक प्लॅनमध्ये समाविष्ट.",
  "AR pictures are illustrations; the look on your phone depends on your camera and room. AR crackers on your real floor need a phone that supports Google Play Services for AR.": "AR चित्रे उदाहरणे आहेत; तुमच्या फोनवरील रूप कॅमेरा आणि खोलीवर अवलंबून आहे. खऱ्या जमिनीवर AR फटाक्यांसाठी Google Play Services for AR असलेला फोन लागतो.",
