  "Cards you make are kept here, ready to play, change or send again.": "तुम्ही बनवलेली कार्ड इथे ठेवली जातात, पुन्हा चालवायला, बदलायला किंवा पाठवायला तयार.",
  "Cards friends send you are kept here, so you can watch them again.": "मित्रमंडळींनी पाठवलेली कार्ड इथे ठेवली जातात, म्हणजे ती पुन्हा पाहता येतात.",
