  "Diya Path and Rocket Rush: 300 more levels each, every chapter now, and unlimited hints ({0} each without Premium).": "दिया पाथ आणि रॉकेट रश: प्रत्येकात आणखी 300 लेव्हल, आत्ताच प्रत्येक प्रकरण, आणि अमर्याद हिंट्स (Premium शिवाय प्रत्येकी {0}).",
  "India in 3D, and in your room": "3D मध्ये भारत, आणि तुमच्या खोलीत",
  "All 15 landmarks in 3D, AR fireworks, and the sacred Diya Path backgrounds.": "सर्व 15 स्मारके 3D मध्ये, AR आतषबाजी, आणि दिया पाथच्या पवित्र पार्श्वभूमी.",
  "All 15 landmarks in 3D, and the sacred Diya Path backgrounds.": "सर्व 15 स्मारके 3D मध्ये, आणि दिया पाथच्या पवित्र पार्श्वभूमी.",
  "A safer streak": "अधिक सुरक्षित स्ट्रीक",
  "Miss a day twice a week and keep your streak and its bigger gifts.": "आठवड्यातून दोनदा एक दिवस चुकला तरी स्ट्रीक आणि तिच्या मोठ्या भेटी कायम राहतात.",
  "You’ve lit {0} kinds of crackers so far. With Premium, all {1} are free.": "आतापर्यंत तुम्ही {0} प्रकारचे फटाके पेटवले आहेत. Premium सोबत सर्व {1} मोफत आहेत.",
  "It’s Diwali week. Light the whole street.": "दिवाळीचा आठवडा आहे. संपूर्ण गल्ली उजळवा.",
  "Diwali is tomorrow. Light the whole street.": "उद्या दिवाळी आहे. संपूर्ण गल्ली उजळवा.",
  "Diwali is in {0} days. Light the whole street.": "दिवाळीला {0} दिवस बाकी. संपूर्ण गल्ली उजळवा.",
  "Changed your mind? You can ask Google Play for a refund within 48 hours of buying.": "विचार बदलला? खरेदीनंतर 48 तासांच्या आत तुम्ही Google Play कडे परतावा मागू शकता.",
