  "Grand finales, wedding cakes, sutli bombs and more. One of each costs {0} without Premium.": "ग्रँड फिनाले, वेडिंग केक, सुतळी बॉम्ब आणि बरेच काही. Premium शिवाय प्रत्येकाचा एक-एक पेटवायला {0} लागतात.",
