  "A grand finale and a wedding cake every evening for a month: {0}. With Premium they’re free, with everything above.": "एक महिना दररोज संध्याकाळी एक ग्रँड फिनाले आणि एक वेडिंग केक: {0}. Premium सोबत ते मोफत, वरच्या सर्व गोष्टींसह.",
