  "Hazaar ladi, saravedi, seven shot, double shot and Lakshmi vedi, lit with your sparkler. Plus no ads and every cracker free.": "हजार माळ, सरवेडी, सेव्हन शॉट, डबल शॉट आणि लक्ष्मी बॉम्ब, तुमच्या फुलबाजीने पेटवा. सोबत जाहिराती नाहीत आणि प्रत्येक फटाका मोफत.",
