  "Chaos: points for the mischief your crackers cause (near people, stalls, roofs, the donkey). Found: today’s hidden stashes on this street.": "धमाल: तुमच्या फटाक्यांच्या खोडसाळपणाचे गुण (लोक, दुकाने, छपरे, गाढवाजवळ). सापडले: या गल्लीतील आजचे लपवलेले साठे.",
  "🏁 Home in {0} · waiting for the others": "🏁 {0} मध्ये पोहोचलात · बाकीच्यांची वाट",
  "Carry 10 kinds of cracker, not 6. Yours for good": "6 नव्हे, 10 प्रकारचे फटाके न्या. कायमचे तुमचे",
  "Golden Lakshmi": "सोनेरी लक्ष्मी",
