  "🗝 Key complete! Steal the {0} from Seth-ji's vault": "🗝 किल्ली पूर्ण! शेठजींच्या तिजोरीतून {0} चोरा",
  "🚨 You have the {0}! RUN to the gate 🏁": "🚨 {0} तुमच्याकडे! दाराकडे पळा 🏁",
  "Seth-ji grabbed it! It fell at your feet. Snatch it back": "शेठजींनी हिसकावले! ते तुमच्या पायाशी पडले. पुन्हा पकडा",
  "🏆 The {0} is yours! It's in your trophy room": "🏆 {0} तुमचे झाले! ते तुमच्या ट्रॉफी खोलीत आहे",
