  "This week's treasure: {0}. Race any street: find the 9 key pieces, open the vault, get it to the gate.": "या आठवड्याचा खजिना: {0}. कोणत्याही गल्लीत शर्यत लावा: 9 किल्लीचे तुकडे शोधा, तिजोरी उघडा, ते दारापर्यंत न्या.",
