  "🏆 I stole the {0} from Seth-ji on {1} in {2} in Pataka Chor! Can you pull off the heist faster? Same street, same stashes:": "🏆 मी पटाका चोरमध्ये {1} वर शेठजींकडून {0} {2} मध्ये चोरले! तुम्ही अजून लवकर चोरी करू शकता? तीच गल्ली, तेच साठे:",
  "Street heist": "गल्लीतली चोरी",
