  "🔥 {0}-day streak · 🎯 Goals {1}/4": "🔥 {0} दिवसांची मालिका · 🎯 उद्दिष्टे {1}/4",
  "🔥 {0}-day streak at risk · play today to keep it": "🔥 {0} दिवसांची स्ट्रीक धोक्यात · आज खेळून टिकवा",
  "Finale firework": "अंतिम आतषबाजी",
  "your showpiece closes the show": "तुमची खास आतषबाजी शो संपवेल",
  "✨ Occasion’s own": "✨ प्रसंगाचे स्वतःचे",
  "Make {0} your card finale for 💎{1}? Tap again": "{0} ला 💎{1} मध्ये तुमच्या कार्डचा शेवट बनवायचा? पुन्हा टॅप करा",
  "🔥 {0} days in a row with {1}": "🔥 {1} सोबत सलग {0} दिवस",
  "💖 {0} watched your sky · 🔥 {1} days in a row": "💖 {0} यांनी तुमचे आकाश पाहिले · 🔥 सलग {1} दिवस",
  "🔥 {0} days with {1}": "🔥 {1} सोबत {0} दिवस",
